import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import { setConsent } from '../../common/sponsors';
/**
 * "Share my email with the sponsor": never ticked unless the member ticked
 * it, separate from entering, and unticking withdraws at once. The sentence
 * is the server's own (the one it stores), with the sponsor's privacy policy
 * beside it.
 */
export default class ConsentBox extends Component {
  busy = false;
  view() {
    const {
      sponsor,
      checked,
      text
    } = this.attrs;
    const id = `ConsentBox-${this.attrs.campaign}-${this.attrs.campaignId}`;
    return m("div", {
      className: "ConsentBox"
    }, m("label", {
      className: "ConsentBox-label",
      for: id
    }, m("input", {
      id: id,
      type: "checkbox",
      checked: checked,
      disabled: this.busy,
      onchange: e => this.toggle(e.target.checked)
    }), m("span", null, this.sentence(text, sponsor.privacyUrl))));
  }

  /** The stored sentence word for word, its privacy-policy address a link. */
  sentence(text, url) {
    const at = url ? text.lastIndexOf(url) : -1;
    if (at < 0) return text;
    return [text.slice(0, at), m("a", {
      className: "ConsentBox-privacy",
      href: url,
      target: "_blank",
      rel: "noopener noreferrer"
    }, url), text.slice(at + url.length)];
  }
  toggle(on) {
    this.busy = true;
    setConsent(this.attrs.campaign, this.attrs.campaignId, on).then(consented => {
      this.attrs.onchange?.(consented);
      app.alerts.show({
        type: 'success'
      }, app.translator.trans(`ernestdefoe-giveaways.forum.sponsors.${consented ? 'shared' : 'withdrawn'}`, {
        sponsor: this.attrs.sponsor.name
      }));
    }).catch(() => {
      /* app.request already showed the alert */
    }).finally(() => {
      this.busy = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-giveaways', 'forum/sponsors/ConsentBox', ConsentBox);